type projectMemberJoins[Q dialect.Joinable] struct {
	typ     string
	Project modAs[Q, projectColumns]
	User    modAs[Q, userColumns]
}

func (j projectMemberJoins[Q]) aliasedAs(alias string) projectMemberJoins[Q] {
	return buildProjectMemberJoins[Q](buildProjectMemberColumns(alias), j.typ)
}

func buildProjectMemberJoins[Q dialect.Joinable](cols projectMemberColumns, typ string) projectMemberJoins[Q] {
	return projectMemberJoins[Q]{
		typ: typ,
		Project: modAs[Q, projectColumns]{
			c: Projects.Columns,
			f: func(to projectColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Projects.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ProjectID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
	}
}
